package archi

import (
	"regexp"
	"strings"
	"unicode"
)

// Folder tree notation: folders become keys ("Business/"), elements are grouped per type as
// {name: id}, relationships per family as lists of compact strings. Folder ids are dropped
// (nothing references them) and regenerated by TreeExpand. Anything that does not fit stays in
// a residual `kids` list of the raw form.

// TopNames maps top-level folder types to their default display names.
var TopNames = map[string]string{
	"strategy": "Strategy", "business": "Business", "application": "Application",
	"technology": "Technology & Physical", "motivation": "Motivation",
	"implementation_migration": "Implementation & Migration", "other": "Other",
	"relations": "Relations", "diagrams": "Views",
}

var typeKeyRe = regexp.MustCompile(`^[A-Z][\pL\pN_]*$`)

func isChildKey(k string) bool {
	if strings.HasSuffix(k, "/") {
		return true
	}
	for _, r := range k {
		return unicode.IsUpper(r)
	}
	return false
}

func asObj(v any) Obj {
	if o, ok := v.(Obj); ok && o != nil {
		return o
	}
	return NewObj()
}

func treeFolder(v Obj, isRoot bool) (string, Obj, bool) {
	for _, k := range v.keys {
		switch k {
		case "kids", "name", "id", "type", "doc", "props":
		default:
			return "", nil, false
		}
	}
	name, _ := v.StrOK("name")
	t, hasT := v.StrOK("type")
	if name == "" {
		return "", nil, false
	}
	if kv, ok := v.Lookup("kids"); ok {
		if _, isList := kv.([]any); !isList {
			return "", nil, false
		}
	}
	var key string
	if isRoot {
		if !hasT {
			if _, top := TopNames[name]; top {
				return "", nil, false
			}
		} else if _, top := TopNames[t]; !top {
			return "", nil, false
		}
		if hasT && t != "" {
			key = t + "/"
		} else {
			key = name + "/"
		}
	} else {
		if hasT {
			return "", nil, false
		}
		key = name + "/"
	}
	ch, rest := treeChildren(v.List("kids"), false)
	val := NewObj()
	if isRoot && hasT && name != TopNames[t] {
		val.Set("name", name)
	}
	for _, a := range []string{"doc", "props"} {
		if v.Has(a) {
			val.Set(a, v.Get(a))
		}
	}
	for _, k := range ch.keys {
		val.Set(k, ch.m[k])
	}
	if len(rest) > 0 {
		val.Set("kids", rest)
	}
	return key, val, true
}

func treeChildren(kids []any, isRoot bool) (Obj, []any) {
	out := NewObj()
	var rest []any
	for _, kid := range kids {
		if !treeKid(kid, isRoot, out) {
			rest = append(rest, kid)
		}
	}
	return out, rest
}

func appendTo(out Obj, key string, item any) {
	l, _ := out.Get(key).([]any)
	out.Set(key, append(l, item))
}

func treeKid(kid any, isRoot bool, out Obj) bool {
	if s, ok := kid.(string); ok {
		m, ok := doMatch(relRe, s)
		if !ok || !REL11[m.g(1)] {
			return false
		}
		appendTo(out, m.g(1), s[len(m.g(1))+1:])
		return true
	}
	ko, ok := kid.(Obj)
	if !ok {
		return false
	}
	if _, _, ok := relItem(kid); ok {
		k, v, _ := ko.Single()
		m, ok := doMatch(relRe, k)
		if !ok || !REL11[m.g(1)] {
			return false
		}
		appendTo(out, m.g(1), O(k[len(m.g(1))+1:], v))
		return true
	}
	k, val, one := ko.Single()
	v, isObj := val.(Obj)
	if !one || !isObj {
		return false
	}
	if k == "folder" {
		fk, fv, ok := treeFolder(v, isRoot)
		if !ok || out.Has(fk) {
			return false
		}
		out.Set(fk, fv)
		return true
	}
	if strings.HasSuffix(k, relSuffix) && REL11[strings.TrimSuffix(k, relSuffix)] && v.Has("id") && !v.Has("_tag") {
		appendTo(out, strings.TrimSuffix(k, relSuffix), v)
		return true
	}
	name, nameOK := v.StrOK("name")
	id, idOK := v.StrOK("id")
	if !(typeKeyRe.MatchString(k) && !REL11[k] && nameOK && !v.Has("_tag") && idOK && id != "") {
		return false
	}
	var g Obj
	if ex, has := out.Lookup(k); has {
		if g, ok = ex.(Obj); !ok {
			return false
		}
	} else {
		g = NewObj()
		out.Set(k, g)
	}
	if g.Has(name) {
		return false
	}
	rest := NewObj()
	for _, a := range v.keys {
		if a != "name" {
			rest.Set(a, v.m[a])
		}
	}
	if rest.KeysAre("id") {
		g.Set(name, id)
	} else {
		g.Set(name, rest)
	}
	return true
}

// TreeCompact turns the flat raw model object into the folder-tree form.
func TreeCompact(obj Obj) Obj {
	rk, mv, ok := obj.Single()
	m, isObj := mv.(Obj)
	if !ok || !isObj {
		return obj
	}
	ch, rest := treeChildren(m.List("kids"), true)
	nm := NewObj()
	for _, k := range m.keys {
		if k != "kids" {
			nm.Set(k, m.m[k])
		}
	}
	for _, k := range ch.keys {
		nm.Set(k, ch.m[k])
	}
	if len(rest) > 0 {
		nm.Set("kids", rest)
	}
	return O(rk, nm)
}

type idGen struct {
	n     int
	taken map[string]bool
}

func (g *idGen) next(prefix string) string {
	for {
		g.n++
		c := prefix + B36(g.n)
		if !g.taken[c] {
			g.taken[c] = true
			return c
		}
	}
}

func untreeChildren(d Obj, isRoot bool, gen *idGen) []any {
	var kids []any
	for _, k := range d.keys {
		v := d.m[k]
		if !isChildKey(k) {
			continue
		}
		switch {
		case strings.HasSuffix(k, "/"):
			name := strings.TrimSuffix(k, "/")
			vo := asObj(v)
			disp := name
			if t, ok := TopNames[name]; ok {
				disp = t
			}
			fv := NewObj()
			fv.Set("name", disp)
			fv.Set("id", "")
			if _, top := TopNames[name]; isRoot && top {
				if n, ok := vo.StrOK("name"); ok {
					fv.Set("name", n)
				} else {
					fv.Set("name", TopNames[name])
				}
				fv.Set("type", name)
			}
			fv.Set("id", gen.next("f"))
			for _, a := range []string{"doc", "props"} {
				if vo.Has(a) {
					fv.Set(a, vo.Get(a))
				}
			}
			sub := append(untreeChildren(vo, false, gen), vo.List("kids")...)
			if len(sub) > 0 {
				fv.Set("kids", sub)
			}
			kids = append(kids, O("folder", fv))
		case REL11[k]:
			items, _ := v.([]any)
			for _, item := range items {
				if s, ok := item.(string); ok {
					kids = append(kids, k+"#"+s)
				} else if ik, iv, ok := relDictForm(item); ok {
					kids = append(kids, O(k+"#"+ik, iv))
				} else {
					kids = append(kids, O(k+relSuffix, item))
				}
			}
		default:
			group, _ := v.(Obj)
			if group == nil {
				continue
			}
			for _, name := range group.keys {
				val := group.m[name]
				rest := NewObj()
				if vo, ok := val.(Obj); ok {
					for _, a := range vo.keys {
						rest.Set(a, vo.m[a])
					}
				}
				eid := rest.Str("id")
				rest.Del("id")
				if eid == "" {
					if s, ok := val.(string); ok && s != "" {
						eid = s
					} else {
						eid = gen.next("e")
					}
				}
				ev := O("name", name, "id", eid)
				for _, a := range rest.keys {
					ev.Set(a, rest.m[a])
				}
				kids = append(kids, O(k, ev))
			}
		}
	}
	return kids
}

// TreeExpand is the inverse of TreeCompact. Folder and element ids are generated avoiding
// every id in obj and in extraIDs.
func TreeExpand(obj Obj, extraIDs map[string]bool) Obj {
	taken := map[string]bool{}
	for k := range extraIDs {
		taken[k] = true
	}
	CollectIDs(obj, taken)
	gen := &idGen{taken: taken}
	rk, mv, ok := obj.Single()
	m, isObj := mv.(Obj)
	if !ok || !isObj {
		return obj
	}
	nm := NewObj()
	for _, k := range m.keys {
		if k != "kids" && !isChildKey(k) {
			nm.Set(k, m.m[k])
		}
	}
	kids := append(untreeChildren(m, true, gen), m.List("kids")...)
	if len(kids) > 0 {
		nm.Set("kids", kids)
	}
	return O(rk, nm)
}
